(function(){const frames=[[20,291,380,299],[420,291,364,299],[804,291,368,299],[20,763,380,299],[420,763,364,299],[804,763,368,299]],names=["Mold development reference illustration","Plastic processing reference illustration","Silicone processing reference illustration","Product assembly reference illustration","Decoration reference illustration","Quality inspection reference illustration"];function update(){if(!/^\/oem-manufacturer\/?$/.test(location.pathname))return;const section=document.querySelector('#manufacturing-capabilities');if(!section)return;section.querySelectorAll('.u-cap-list>div').forEach((card,i)=>{if(i>5||card.querySelector('.u-cap-supplied-frame'))return;card.querySelector('.u-capability-photo')?.remove();const wrap=document.createElement('div');wrap.className='u-cap-supplied-frame';const[x,y,w,h]=frames[i];wrap.style.cssText='--crop-x:'+x+';--crop-y:'+y+';--crop-w:'+w+';--crop-h:'+h;const img=document.createElement('img');img.className='u-capability-photo';img.src='/img/oem-capabilities-supplied-20261109/capability-reference-sheet.png';img.alt=names[i];img.width=1190;img.height=1322;img.loading='lazy';wrap.append(img);card.insertBefore(wrap,card.firstChild);});if(!section.querySelector('.u-cap-supplied-disclosure')){const p=document.createElement('p');p.className='u-cap-supplied-disclosure';p.textContent='Process illustrations supplied for presentation; not photographs of the BOOM production floor. Confirm the material, process and manufacturing scope for your selected model.';section.querySelector('.u-cap-list').insertAdjacentElement('afterend',p);}}let p=false;new MutationObserver(()=>{if(!p){p=true;setTimeout(()=>{p=false;update();},90);}}).observe(document.documentElement,{childList:true,subtree:true});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',update):update();})();